query:
mutation notificationIntegrationCreateWebhook ( $accountId:ID! $createWebhookInput:CreateWebhookInput!) {
	notification ( accountId:$accountId ) {
		integration {
			createWebhook ( input:$createWebhookInput   ) {
				webhook {
					id
					name
					enabled
					url
					requestMethod
					auth {
						authType
						... on BasicAuth {
							username
						}
						... on CustomHeaderAuth {
							name
						}
						... on CustomHeadersAuth {
							plainHeaders {
								name
								value
							}
							secretHeaders {
								name
							}
						}
					}
					header {
						name
						value
					}
					body
					responseMapping {
						key
						value
					}
					relatedWebhookId
				}
			}
		}
	}	
}
